F = {}
F['consultant'] = dict(noun='consultant', nouns='consultants', practice='consultancy', hub='management-consultants', group='consulting',
 regulator=["Most consultancy work is not regulated by a single body, so it pays to check credentials yourself. Relevant memberships include the Chartered Management Institute (CMI), the CIPD for HR professionals, BCS for IT professionals, and industry-specific bodies for compliance specialists. Ask for case studies and references from similar clients.","Where a consultant's work touches regulated areas, such as financial services compliance, data protection or employment law, check that they are clear about the limits of their role and when you need a solicitor or other regulated adviser."],
 scenarios=["a growing business that needs structure, processes or a plan","a problem with profitability, cash flow or operations","preparing for investment, sale or succession","a new regulatory requirement to meet","people issues such as restructuring or policies","technology choices, security or system upgrades","a project that needs extra expertise for a fixed period","an independent review before a big decision"],
 prepare=["a short description of the problem or goal","your sector, size and locations","what you have already tried","the outcome you would count as success","your timescale and any fixed deadlines","who in your team will work with the consultant","relevant documents, such as plans or policies","budget expectations, so scope can be matched"],
 questions=["What experience do you have with businesses like mine?","Can you share case studies or references?","Who exactly will do the work?","How will you charge: day rate, fixed fee or retainer?","What will you deliver, and by when?","How will we measure success?","How will you hand over knowledge so we are not dependent on you?","What professional memberships and insurance do you hold?"],
 fees=["Consultants usually charge day rates, fixed fees for defined projects, or monthly retainers. A clear proposal setting out deliverables and timescales is the best way to compare options. iComply does not publish fees; the consultancy quotes you, POA.","Ask for a written proposal with milestones, and agree how changes in scope will be handled."],
 red_flags=["vague deliverables","no references or relevant experience","open-ended contracts with no review points","promises of guaranteed results","no professional indemnity insurance"],
 timeline="Initial conversations can often happen within a week. Short reviews may take a few weeks; larger projects run for months with agreed milestones.",
 after="Once introduced, the consultancy will usually hold a discovery call and send a proposal. The contract and delivery are between you and the consultancy. iComply does not deliver consultancy work.",
 faqs=[("How do I know a consultant is any good?","Ask for references from similar clients, relevant case studies and clear deliverables. A good consultant is happy to show their track record."),("Can I hire a consultant for a short project?","Yes. Many consultants work on short, defined pieces of work such as a review, a policy update or a workshop.")])
F['recruitment'] = dict(noun='recruitment agency', nouns='recruitment agencies', practice='recruitment agency', hub='recruitment-consultants', group='consulting',
 regulator=["Employment agencies and businesses in the UK must follow the Conduct of Employment Agencies and Employment Businesses Regulations, enforced by the Employment Agency Standards Inspectorate. Agencies cannot usually charge work-seekers for finding them work. Membership of the Recruitment and Employment Confederation (REC) or APSCo shows commitment to an industry code.","Agencies supplying temporary workers have obligations on pay, holiday and right-to-work checks. Clear terms of business for employers, and clear contracts for workers, are essential."],
 scenarios=["an employer struggling to fill a skilled role","seasonal or temporary staffing needs","a graduate scheme or entry-level hiring round","senior or executive appointments","specialist technical roles such as IT","a job seeker wanting help finding a new role","building a team quickly for a new contract","replacing staff while keeping the business running"],
 prepare=["the role, responsibilities and must-have skills","salary range or day rate","location, hybrid or remote arrangements","permanent, contract or temporary","how quickly you need someone","your interview process","for job seekers: an up-to-date CV","for job seekers: the roles and locations you are interested in"],
 questions=["Do you specialise in my sector or role type?","How do you find and screen candidates?","What are your terms of business and fees?","Is there a rebate or replacement period if a hire leaves early?","How do you handle right-to-work checks?","How quickly can you provide a shortlist?","Are you REC or APSCo members?","How will you keep me updated?"],
 fees=["Agencies typically charge employers a placement fee for permanent hires or a margin on temporary workers' pay. Terms differ, so always agree them in writing before receiving CVs. Agencies generally cannot charge job seekers for finding work. iComply does not publish fees; the agency quotes you, POA.","Check rebate terms and what happens if you hire a candidate introduced by the agency later."],
 red_flags=["charges to job seekers for finding work","CVs sent without the candidate's permission","no written terms of business","vague screening processes","pressure to hire quickly"],
 timeline="Agencies can often begin sourcing within days. Shortlists for common roles may come within a week or two; senior or niche roles take longer.",
 after="Once introduced, the agency will take a brief and confirm terms. The recruitment relationship is between you and the agency. iComply does not recruit staff.",
 faqs=[("Do job seekers pay recruitment agencies?","Generally no. UK rules mean agencies usually cannot charge work-seekers for finding them work."),("What is a rebate period?","An agreed period after a permanent hire during which the agency refunds part of its fee or finds a replacement if the person leaves.")])
F['education'] = dict(noun='education consultant', nouns='education consultants', practice='education consultancy', hub='education-consultants', group='consulting',
 regulator=["Education consultancy is not regulated by a single body. Look for consultants with relevant teaching, admissions or special educational needs experience, and membership of organisations such as the Society of Education Consultants. Ask for references and a clear written agreement.","For school admission appeals, independent appeal panels follow the School Admission Appeals Code in England. A consultant can help you prepare, but they cannot guarantee a result."],
 scenarios=["choosing between state and independent schools","moving to the UK and finding a school place","preparing for entrance exams or interviews","appealing against a school admission decision","support for a child with special educational needs","university and course choices","study options abroad","changing schools mid-year"],
 prepare=["your child's age, year group and current school","the schools or areas you are considering","key dates such as application deadlines","any reports or assessments","special educational needs or EHCP information","your priorities, such as distance or specialism","any refusal letters, for appeals","your budget expectations for fees"],
 questions=["What experience do you have with schools in my area?","How do you charge, and what is included?","Do you have experience with admission appeals?","How do you support children with additional needs?","Can you provide references?","How will you communicate with us?","Will you attend meetings or hearings with us?","What are realistic outcomes in our situation?"],
 fees=["Education consultants usually charge for an initial consultation, then a fixed fee for a package or an hourly rate. iComply does not publish fees; the consultant quotes you, POA.","Get the scope in writing, especially for appeals, so you know what preparation and attendance are included."],
 red_flags=["guaranteed places or appeal outcomes","no relevant experience","no written agreement","pressure to buy extensive packages","vague advice on deadlines"],
 timeline="Initial consultations are often available within a week. Admission deadlines and appeal timetables are fixed, so include them in your enquiry.",
 after="Once introduced, the consultant will discuss your situation and agree terms. The advice relationship is between you and them. iComply does not provide education advice.",
 faqs=[("Can a consultant guarantee a school place?","No. They can help you make strong applications and prepare for appeals, but decisions rest with schools and appeal panels."),("When should we start planning?","As early as possible, ideally a year before applications are due, especially for selective or independent schools.")])
F['planning'] = dict(noun='planning consultant', nouns='planning consultants', practice='planning consultancy', hub='planning-consultants', group='property-prof',
 regulator=["Many planning consultants are chartered members of the Royal Town Planning Institute (RTPI), shown by the letters MRTPI. Chartered members follow the RTPI's code of professional conduct. You can check the RTPI directory before appointing anyone.","Planning consultants work alongside architects, surveyors and specialist consultants such as heritage, ecology and highways experts. A good consultant will tell you early whether a scheme is realistic under local policy."],
 scenarios=["a planning application for a new home or extension","a refused application that may be appealed","converting a building to a different use","land with development potential","a listed building or conservation area project","objecting to or commenting on a neighbour's application","pre-application advice with the council","permitted development and lawful development certificates"],
 prepare=["the site address and a location plan","what you want to build or change","planning history, including any refusals","drawings or sketches, if you have them","constraints such as listed status or flood zones","your timescale","the other consultants you have appointed","any council correspondence"],
 questions=["Are you an RTPI chartered member?","What is your experience with this council?","What are the main planning risks for my scheme?","Should we seek pre-application advice?","What other reports will the council need?","How do you charge for applications and appeals?","How long will the process take?","What happens if the application is refused?"],
 fees=["Planning consultants usually charge fixed fees for defined stages, such as an appraisal, application or appeal, or hourly rates for advice. Council application fees are separate. iComply does not publish fees; the consultant quotes you, POA.","Ask what reports and meetings are included, and how appeals would be charged."],
 red_flags=["guaranteed planning permission","no RTPI or relevant experience","no written scope","vague answers about local policy","pressure to submit before the scheme is ready"],
 timeline="Simple applications are often decided within around eight weeks of validation, major applications within thirteen, though delays are common. Appeals take several months.",
 after="Once introduced, the consultant will review the site and agree a scope. The professional relationship is between you and them. iComply does not provide planning advice.",
 faqs=[("Do I need planning permission?","It depends on the work, the property and its location. Some changes fall under permitted development; a consultant can advise or apply for a lawful development certificate."),("Can I appeal a refusal?","Usually yes, to the Planning Inspectorate in England, within strict deadlines that depend on the type of application.")])
F['care'] = dict(noun='care advisor', nouns='care advisors', practice='later-life care advice service', hub='care-advisors', group='finance',
 regulator=["Care homes and home care agencies in England are registered with and rated by the CQC; Wales, Scotland and Northern Ireland have their own regulators. Care fees advice that involves financial products, such as immediate needs annuities, is regulated by the FCA, and the Society of Later Life Advisers (SOLLA) accredits specialist advisers.","Local councils assess care needs and finances, and must provide information and advice. Independent advisers can help families understand options, but they should be clear whether their advice is regulated."],
 scenarios=["a parent who can no longer manage safely at home","choosing between home care and a care home","understanding how care is funded and assessed","selling a home to pay for care","NHS Continuing Healthcare eligibility","a hospital discharge that needs care in place quickly","comparing local care homes","planning ahead for later life"],
 prepare=["the person's current needs and health conditions","where they live and where family live","any council needs assessment","an overview of income, savings and property","powers of attorney in place","preferences about home or residential care","the timescale, especially around hospital discharge","questions about funding"],
 questions=["Is your advice regulated, and are you SOLLA accredited?","How do you charge?","Can you help with council assessments and NHS Continuing Healthcare?","How do you compare care homes?","What funding options are realistic in our situation?","How does the property disregard or a deferred payment agreement work?","Can you work with our solicitor?","What support do you offer after a decision?"],
 fees=["Care advisers may charge a fixed fee, an hourly rate, or (for regulated product advice) a fee or commission that must be disclosed. iComply does not publish fees; the adviser quotes you, POA.","Ask whether initial guidance is free, and for written terms before detailed advice."],
 red_flags=["unregulated advice on financial products","pressure to sell property quickly","no mention of council assessments","advice that ignores entitlement to free care","unclear fees"],
 timeline="Hospital discharge can move quickly, so mention it in your enquiry. Planned moves allow time to visit homes and get advice.",
 after="Once introduced, the adviser will discuss the situation and agree terms. Advice is between you and the adviser. iComply does not provide care or financial advice.",
 faqs=[("Who pays for care?","It depends on needs, income and assets. Councils carry out financial assessments, and some people qualify for NHS Continuing Healthcare. An adviser can explain how the rules apply to you."),("Can a care home take my house?","Property may be counted in the financial assessment in some circumstances, but there are disregards and deferred payment options. Get advice early.")])
F['funeral'] = dict(noun='funeral director', nouns='funeral directors', practice='funeral home', hub='funeral-directors', group='general',
 regulator=["Funeral directors are not licensed in England, but many belong to the National Association of Funeral Directors (NAFD) or the National Society of Allied and Independent Funeral Directors (SAIF), which have codes of practice. Scotland has a statutory code of practice for funeral directors. Since 2022, providers of pre-paid funeral plans must be authorised by the FCA.","The Competition and Markets Authority requires funeral directors to display standardised price lists, so you can compare costs clearly."],
 scenarios=["a death at home, in hospital or in a care home","arranging a burial or cremation","a direct cremation without a service","a religious or cultural funeral with specific requirements","a death abroad requiring repatriation","planning and paying for a funeral in advance","a family on a limited budget","an eco or woodland burial"],
 prepare=["the name of the person who has died and where they are now","whether a medical certificate has been issued","any known wishes, such as burial or cremation","religious or cultural requirements","whether there is a pre-paid funeral plan","who is making the arrangements","a rough idea of budget","preferred dates and places"],
 questions=["Are you a member of NAFD or SAIF?","Can I see your standardised price list?","What is included, and what are third-party costs?","Can you support our religious or cultural needs?","When is payment due?","Can we visit the person who has died?","How do you handle direct cremation?","If you sell funeral plans, are you FCA authorised?"],
 fees=["Funeral costs include the funeral director's charges and third-party costs such as cremation or burial fees. Funeral directors must show a standardised price list. iComply does not publish prices; the funeral director quotes you, POA.","If you receive certain benefits, you may be able to apply for help with funeral costs from the government."],
 red_flags=["no published price list","pressure to buy extras","unclear third-party costs","funeral plans sold by firms not authorised by the FCA","poor communication"],
 timeline="Funerals are often held within a few weeks of death, depending on registration, availability and any coroner's involvement.",
 after="Once introduced, the funeral director will contact you to discuss arrangements. The arrangement is between you and them. iComply is a matching service only.",
 faqs=[("What do I need to do first after a death?","If the death was expected, contact the GP or nurse to confirm it. A medical certificate is needed before the death can be registered. A funeral director can guide you through the next steps."),("What is direct cremation?","A cremation without a funeral service. Families can then hold a memorial separately.")])
F['notary'] = dict(noun='notary', nouns='notaries', practice='notary public', hub='notaries', group='legal',
 regulator=["Notaries in England and Wales are qualified lawyers regulated by the Faculty Office of the Archbishop of Canterbury, which keeps a register of practising notaries. They must hold insurance and follow practice rules. In Scotland, notaries are solicitors admitted as notaries public.","Notaries authenticate documents for use abroad, witness signatures, verify identity and arrange legalisation or apostilles through the Foreign, Commonwealth and Development Office."],
 scenarios=["documents needed for a property purchase abroad","a power of attorney for use overseas","company documents for a foreign bank or authority","certified copies of passports or qualifications","statutory declarations for overseas use","marriage or adoption paperwork abroad","apostille or embassy legalisation","translations that need notarisation"],
 prepare=["the documents to be notarised","which country they are for","instructions from the receiving authority","photo ID and proof of address","company documents, if signing for a company","deadlines","whether an apostille or embassy legalisation is needed","the number of copies required"],
 questions=["Are you on the Faculty Office register?","Is your fee fixed for this work?","Can you arrange the apostille or legalisation?","How long will it take?","Do you offer home or office visits?","What ID do I need to bring?","Can you handle documents in a foreign language?","What happens if the receiving country rejects the document?"],
 fees=["Notaries usually charge a fixed fee per document or appointment, with apostilles and legalisation charged separately. iComply does not publish fees; the notary quotes you, POA.","Ask whether courier costs and embassy fees are included."],
 red_flags=["not on the Faculty Office register","unclear fees","no ID checks","no knowledge of the destination country's requirements","promises that cannot be met on timing"],
 timeline="Appointments are often available within days. Apostilles and embassy legalisation can add days or weeks.",
 after="Once introduced, the notary will confirm requirements and book an appointment. The service is between you and them. iComply does not notarise documents.",
 faqs=[("What is an apostille?","A certificate from the FCDO confirming a UK public official's signature or seal, so a document is accepted in countries that are part of the Hague Convention."),("Is a notary the same as a solicitor?","No. Notaries are a separate branch of the legal profession, specialising in documents for use abroad. Some are also solicitors.")])
